package game.sanguo.core;
import java.nio.file.*;import java.util.*;
public final class ActualThreePersonCampaignProbe{
 public static void main(String[]args)throws Exception{for(String arg:args){Path p=Path.of(arg);byte[]raw=Files.readAllBytes(p);World w=SaveCodec.decode(raw);byte[]canonical=SaveCodec.encode(w);if(!Arrays.equals(canonical,SaveCodec.encode(SaveCodec.decode(canonical))))throw new AssertionError("complete World/all RNG cold");System.out.println("FILE="+p.getFileName()+" SHA="+PcCommandCapacityPolicy.hex(java.security.MessageDigest.getInstance("SHA-256").digest(raw))+" turn="+w.turn+" campaignRng="+w.strategy.getRandomState());var s=w.contests.current();if(s!=null&&s.nativeDuel!=null){System.out.println("contest="+s.id+" inputs="+s.nativeDuel.inputs+" round="+s.nativeDuel.state.model.get(0x10)+" frame="+s.nativeDuel.frames+" winner="+PcDuelKernel.readManager(s.nativeDuel.state.manager,0x54));}var u=w.unit(1);System.out.println("UNIT="+(u==null?"none":u.officerId+" deputies="+Arrays.toString(u.deputies)+" cell="+u.hex+" troops="+u.troops+" energy="+u.energy+" gold="+u.gold));for(int nativeId:new int[]{98,432,635}){var f=PcDuelSourceFacts.saved(w).values().stream().filter(v->v.nativeId==nativeId).findFirst().orElseThrow();var o=w.officer(f.officerId);System.out.println("crew="+o.id+" native="+nativeId+" name="+o.name+" injury="+w.contests.injury(o.id)+" unit="+o.unitId+" city="+o.cityId+" present="+w.life.present(o.id)+" war="+w.officerAbilities.currentWithInjury(o.id,1,w.contests.injury(o.id)));}if(u!=null&&s==null){for(var e:w.units)if(w.campaign.hostile(u.owner,e.owner)&&u.hex.distance(e.hex)<=8){System.out.println("enemy="+e.id+" native="+PcDuelSourceFacts.saved(w).get(e.officerId).nativeId+" name="+w.officer(e.officerId).name+" cell="+e.hex+" distance="+u.hex.distance(e.hex)+" error="+w.contests.duelError(1,e.id));for(var member:w.army.crew(e)){var admission=PcDuelAdmissionRules.current(w,member.id);System.out.println("opponentMember="+member.id+" native="+admission.nativeId+" name="+member.name+" health="+admission.health+" war="+admission.war+" injury="+w.contests.injury(member.id));}var leftStats=PcDuelUnitStats.currentCombat(w,u);var rightStats=PcDuelUnitStats.currentCombat(w,e);System.out.println("factor="+PcDuelResponseRules.unitFactor(u.troops,e.troops,leftStats.attack,leftStats.defense,rightStats.attack,rightStats.defense)+" leftTroops="+u.troops+" rightTroops="+e.troops+" ownDrumWithin3="+PcDuelResponseRules.currentDrumSupport(w,u.officerId,e.hex));if(w.contests.duelError(1,e.id)==null)for(var c:w.contests.nativeDuelCandidates(1,e.id))System.out.println("nominee="+c.officerId+" chance="+c.chance);}}if(!Arrays.equals(raw,Files.readAllBytes(p)))throw new AssertionError("original evidence changed");}System.out.println("PASS read-only actual terminal/campaign facts; no new APK result");}
}
